(()=>{'use strict';const B='https://woongbi-quote-api.woongbts.workers.dev';let C=null,P=null;async function loadCatalog(){if(C)return C;if(P)return P;P=(async()=>{let last;for(let i=0;i<3;i++){const ctl=typeof AbortController!=='undefined'?new AbortController():null,t=ctl?setTimeout(()=>ctl.abort(),8000):0;try{const r=await fetch(B+'/catalog/mvno',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}',signal:ctl?.signal});const d=await r.json().catch(()=>({}));if(r.ok&&d?.ok===true&&d.catalog){C=d.catalog;document.documentElement.dataset.mvnoApi='ready';window.dispatchEvent(new CustomEvent('woongbi:mvno-api-ready',{detail:C}));return C}last=new Error(d?.error||('mvno-api-'+r.status))}catch(e){last=e}finally{if(t)clearTimeout(t)}if(i<2)await new Promise(r=>setTimeout(r,500*(i+1)))}document.documentElement.dataset.mvnoApi='unavailable';window.dispatchEvent(new CustomEvent('woongbi:mvno-api-unavailable'));throw last||new Error('mvno-api-unavailable')})().finally(()=>{P=null});return P}window.WoongbiMvnoApi={loadCatalog};})();
